import re
def block_status(block):
    if not isinstance(block,dict) or set(block)!={'kind','text','page','block','table','row'}:
        return 'rejected'
    if not isinstance(block['kind'],str) or block['kind'] not in {'heading','paragraph','table_row'}:
        return 'rejected'
    try:
        text=valid_text(block['text'])
    except ValueError:
        return 'rejected'
    if not text.strip() or len(text)>1000:
        return 'rejected'
    if any(type(block[k]) is not int or block[k]<1 for k in ('page','block')):
        return 'rejected'
    table,row=block['table'],block['row']
    if table is not None and (not isinstance(table,str) or re.fullmatch(r'[A-Za-z0-9._-]{1,128}',table) is None):
        return 'rejected'
    if row is not None and (type(row) is not int or row<1):
        return 'rejected'
    review='�' in text
    if block['kind']=='table_row':
        review=review or table is None or row is None or re.search(r'product=[^;]+; quantity=[0-9,]+(?:\.[0-9]+)? (?:kg|ea); unit price=USD [0-9]+\.[0-9]{2}\.?$',text) is None
    return 'needs_review' if review else 'accepted'

