def span_locations(blocks,start,end):
    if not isinstance(blocks,(list,tuple)):
        raise ValueError("list or tuple required")
    clean=[valid_text(x).strip() for x in blocks]
    if any(not x for x in clean):
        raise ValueError("blank block")
    total=sum(len(x) for x in clean)+max(0,len(clean)-1)
    if type(start) is not int or type(end) is not int or not 0<=start<end<=total:
        raise ValueError("invalid window range")
    result=[]
    cursor=0
    for index,text in enumerate(clean):
        lo,hi=max(start,cursor),min(end,cursor+len(text))
        if lo<hi:
            result.append((index,lo-cursor,hi-cursor))
        cursor+=len(text)+1
    return result

