import re
def sentence_groups(text,target):
    valid_text(text)
    if type(target) is not int or target<1:
        raise ValueError("positive exact-int target required")
    if not text.strip():
        return []
    groups=[]
    pending=[]
    for sentence in re.split(r'(?<=[.!?])\s+',text.strip()):
        if pending and len(' '.join([*pending,sentence]))>target:
            groups.append(' '.join(pending))
            pending=[]
        pending.append(sentence)
    if pending:
        groups.append(' '.join(pending))
    return groups

def structure_units(blocks,include_heading=True):
    if type(include_heading) is not bool:
        raise ValueError("exact bool required")
    heading=None
    result=[]
    for block in blocks:
        if block['kind']=='heading':
            heading=block
            continue
        if include_heading and heading is not None:
            result.append((heading['text']+'\n'+block['text'],(heading['location'],block['location'])))
        else:
            result.append((block['text'],(block['location'],)))
    return result

