import math
def checked_number(value,lo,hi):
    if type(value) not in (int,float):
        raise ValueError("exact numeric value required")
    try:
        value=float(value)
    except OverflowError as exc:
        raise ValueError("finite number required") from exc
    if not math.isfinite(value) or not lo<=value<=hi:
        raise ValueError("number outside domain")
    return value

def paragraph_groups(paragraphs,scores,threshold):
    threshold=checked_number(threshold,0,1)
    if not isinstance(paragraphs,(list,tuple)) or not isinstance(scores,(list,tuple)):
        raise ValueError("lists or tuples required")
    clean=[valid_text(x).strip() for x in paragraphs]
    if any(not x for x in clean) or len(scores)!=max(0,len(clean)-1):
        raise ValueError("invalid paragraphs/adjacent count")
    values=[checked_number(s,-1,1) for s in scores]
    if not clean:
        return []
    result=[]
    pending=[clean[0]]
    for score,text in zip(values,clean[1:]):
        if score<threshold:
            result.append(' '.join(pending))
            pending=[]
        pending.append(text)
    result.append(' '.join(pending))
    return result

