import json,hashlib
def representation_hash(record):
    if not isinstance(record,dict):
        raise ValueError("representation object required")
    try:
        encoded=json.dumps(record,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')
    except (TypeError,ValueError,UnicodeEncodeError) as exc:
        raise ValueError("invalid representation") from exc
    return hashlib.sha256(encoded).hexdigest()

