def same_lineage(child,parent):
    return (child['parent'] is not None and child['parent']==parent['id']
            and parent['parent'] is None and child['source']==parent['source']
            and child['policy']==parent['policy'])

def expand_units(ranked_ids,records,can_read):
    selected=[]
    seen=set()
    for hit_id in ranked_ids:
        if hit_id not in records:
            raise ValueError("unknown ranked hit")
        hit=records[hit_id]
        if not can_read(hit):
            continue
        candidate=hit
        if hit['parent'] is not None:
            candidate=records.get(hit['parent'])
            if candidate is None or not same_lineage(hit,candidate):
                raise ValueError("invalid parent lineage")
            if not can_read(candidate):
                continue
        if candidate['id'] not in seen:
            selected.append(candidate)
            seen.add(candidate['id'])
    return selected

def admit_context(units,budget):
    if type(budget) is not int or budget<1:
        raise ValueError("positive exact-int budget required")
    selected=[]
    used=0
    for unit in units:
        cost=len(unit['text'])+(1 if selected else 0)
        if used+cost<=budget:
            selected.append(unit['id'])
            used+=cost
    return selected

