def document_recall(ranked_documents,gold,k):
    if type(k) is not int or k<1 or not isinstance(ranked_documents,(list,tuple)) or not isinstance(gold,(set,frozenset)):
        raise ValueError("invalid ranking or cutoff")
    if any(not valid_text(x).strip() for x in [*ranked_documents,*gold]):
        raise ValueError("nonblank IDs required")
    if not gold:
        return None
    return len(set(ranked_documents[:k]) & gold)/len(gold)

def support_fraction(context,support):
    if not support:
        return None
    complete=0
    for document,atoms in support.items():
        text='\n'.join(x['text'] for x in context if x['document_id']==document).casefold()
        complete+=all(atom.casefold() in text for atom in atoms)
    return complete/len(support)

