def policy_summary(chunks,dimension,parent_child=False):
    if not isinstance(chunks,(list,tuple)) or type(dimension) is not int or dimension<1 or type(parent_child) is not bool:
        raise ValueError("invalid summary parameters")
    stored_bytes=text_storage(chunks)
    stored=len(chunks)
    indexed=sum(x['parent'] is not None for x in chunks) if parent_child else stored
    return {'stored_chunk_count':stored,'indexed_chunk_count':indexed,
            'average_stored_chunk_chars':sum(len(x['text']) for x in chunks)/stored if stored else None,
            'stored_text_utf8_bytes':stored_bytes,
            'packed_float32_vector_bytes_estimate':indexed*dimension*4,
